  apply (fire_of_run_instr tm Cc false true l A0_1RB1LA_0LA1RC_0RD0RB_0LD1LB p j (Ap_Alph_10_11_11 q0 ++ [S0]) []);
    [exact Hst | discriminate | reflexivity | exact (gsi_1RB1LA_0LA1RC_0RD0RB_0LD1LB p j q0 E)].
Qed.


(** An instruction that fires ONLY inside the interior lap: [vis_via_ovf] runs to an
    OVERFLOW anchor, so it cannot see one.  This is the interior witness, and
