(** 1RB1LA_0LA1RC_0RD0RB_1LB1LB *)
Definition tm_1RB1LA_0LA1RC_0RD0RB_1LB1LB : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S1 DL StA
  | StB, S0 => mk S0 DL StA | StB, S1 => mk S1 DR StC
  | StC, S0 => mk S0 DR StD | StC, S1 => mk S0 DR StB
  | StD, S0 => mk S1 DL StB | StD, S1 => mk S1 DL StB end.
(** the instructions the certificate claims NEVER fire; the lap
    argument runs on the machine WRAPPED at them
    ([WrapTr.tm_wrap_trs]), so a pinned instruction firing would
    halt it and every [srun] below would fail. *)
Definition pins_1RB1LA_0LA1RC_0RD0RB_1LB1LB : list Instr := [(StD, S0)].
Definition tmw_1RB1LA_0LA1RC_0RD0RB_1LB1LB : TM := tm_wrap_trs tm_1RB1LA_0LA1RC_0RD0RB_1LB1LB pins_1RB1LA_0LA1RC_0RD0RB_1LB1LB.
