Definition chn_1RB1LA_0LA1RC_0RD0RB_1LB1LB : list lstep := [SWin 2; SCycL 2 0; SWin 4; SCycR 2; SWin 2].

Lemma run_inner_1RB1LA_0LA1RC_0RD0RB_1LB1LB : srun tm false true chn_1RB1LA_0LA1RC_0RD0RB_1LB1LB AI0_1RB1LA_0LA1RC_0RD0RB_1LB1LB = Some (AI1_1RB1LA_0LA1RC_0RD0RB_1LB1LB, 4, 8).
