(** *** exit: the last inner all-ones fill -> the outer successor *)
Definition BE0_1RB1LA_0LA1RC_0RD0RB_1LB1LB : sconf := mkC StA (mkS [] [S1;S1] 1 0 [S1;S1]) S0 (mkS [S0;S1] [] 0 0 []).
Definition che_1RB1LA_0LA1RC_0RD0RB_1LB1LB : list lstep := [SWin 2; SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWin 3; SRotL 1; SFoldL 1].

