  unfold Cin_1RB1LA_0LA1RC_0RD0RB_1LB1LB, cden, AI0_1RB1LA_0LA1RC_0RD0RB_1LB1LB; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
