  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB1LA_0LC1RD_1LD1LA_0LA0RB
      with (l := [SRotL 1; SWin 1]).
    vm_compute; reflexivity.
