  apply (nested_overflow_lift tm Cc Cin lapin_1RB1LA_0LC1RD_1LD1RD_0LA0RB p (pow2 j)).
  - exists (4 * j + 7), (cden [] [] j BB1_1RB1LA_0LC1RD_1LD1RD_0LA0RB).
    split; [lia|]. split; [| exact (gbo_1RB1LA_0LC1RD_1LD1RD_0LA0RB j)].
    rewrite (gso_1RB1LA_0LC1RD_1LD1RD_0LA0RB p j E).
    exact (srun_sound tm true true chb_1RB1LA_0LC1RD_1LD1RD_0LA0RB B0_1RB1LA_0LC1RD_1LD1RD_0LA0RB BB1_1RB1LA_0LC1RD_1LD1RD_0LA0RB 4 7
             run_boot_1RB1LA_0LC1RD_1LD1RD_0LA0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 15), (cden [] [] j B1_1RB1LA_0LC1RD_1LD1RD_0LA0RB).
    split; [| exact (geo_1RB1LA_0LC1RD_1LD1RD_0LA0RB p j E)].
    rewrite (gxi_1RB1LA_0LC1RD_1LD1RD_0LA0RB j).
