    family's own overflow decomposition names the word. *)
Lemma gxi_1RB1LA_0LC1RD_1RD0RB_0LA0RB : forall j, Cin (fill (pow2 j)) = cden [] [] j BE0_1RB1LA_0LC1RD_1RD0RB_0LA0RB.
