             run_boot_1RB1LA_0LC1RD_1RD0RB_0LA0RB [] [] j ltac:(reflexivity) ltac:(reflexivity)).
  - exists (4 * j + 9), (cden [] [] j B1_1RB1LA_0LC1RD_1RD0RB_0LA0RB).
