Lemma gen_1RB1LA_0LC1RD_1RD1LC_0LA0RB : forall v i q0, cview v = (i, Some q0) ->
  lift (cden (Ip q0 ++ [S1]) [] i AI1_1RB1LA_0LC1RD_1RD1LC_0LA0RB) = lift (Cin (Pos.succ v)).
