  exists (4 * i + 8), (cden (Ip q0 ++ [S1]) [] i AI1_1RB1LA_0LC1RD_1RD1LC_0LA0RB).
  split; [lia|]. split; [| exact (gen_1RB1LA_0LC1RD_1RD1LC_0LA0RB v i q0 E)].
  rewrite (gsn_1RB1LA_0LC1RD_1RD1LC_0LA0RB v i q0 E).
  exact (srun_sound tm false true chn_1RB1LA_0LC1RD_1RD1LC_0LA0RB AI0_1RB1LA_0LC1RD_1RD1LC_0LA0RB AI1_1RB1LA_0LC1RD_1RD1LC_0LA0RB 4 8
           run_inner_1RB1LA_0LC1RD_1RD1LC_0LA0RB (Ip q0 ++ [S1]) [] i
           ltac:(discriminate) ltac:(reflexivity)).
