  - destruct (cview_pos p j E) as (j' & ->). exact (lapo_1RB1LA_0LC1RD_1RD1RD_0LA0RB p j' E).
Qed.

(** ** Bootstrap *)

Lemma bootq_1RB1LA_0LC1RD_1RD1RD_0LA0RB : stepn tm_1RB1LA_0LC1RD_1RD1RD_0LA0RB 7 InitES = Some (lift (Cc 1)).
